from pathlib import Path
import json,html
root=Path(__file__).parent
chapters=json.loads((root/'content.json').read_text())
nav=''.join(f'<a href="#{c["id"]}">{c["label"]}</a>' for c in chapters)
sections=''.join(f'''<section id="{c['id']}" data-title="{html.escape(c['title'])}"><div class="eyebrow">{c['label']}</div><h2>{c['title']}</h2>{c['body']}<details class="feedback"><summary>Notes and feedback · {c['label']}</summary><label for="note-{c['id']}">What should be clarified, corrected, or expanded?</label><textarea id="note-{c['id']}" data-note="{c['id']}" rows="5" placeholder="Refer to a sentence, result, or idea, then describe the change you want."></textarea><label class="reviewed"><input type="checkbox" data-reviewed="{c['id']}"> I have reviewed this section</label></details></section>''' for c in chapters)
shell=r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Energy-aware AI scheduling · Research reading document</title>
<style>
:root{color-scheme:light dark;--bg:#f5f3ee;--paper:#fffefa;--fg:#202e36;--muted:#52636d;--line:#d6ddd9;--accent:#16685e;--soft:#e9f2ee;--button:#174e48;--buttontext:#fff;--serif:Georgia,'Times New Roman',serif}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--fg);font:17px/1.75 system-ui,sans-serif}a{color:var(--accent);text-underline-offset:4px}button,input,textarea{font:inherit}button{border:1px solid var(--line);border-radius:6px;background:var(--paper);color:var(--fg);padding:8px 13px;cursor:pointer}button.primary{background:var(--button);color:var(--buttontext);border-color:var(--button)}button:hover{filter:brightness(.94)}button:focus-visible,a:focus-visible,textarea:focus-visible,summary:focus-visible{outline:3px solid var(--accent);outline-offset:4px}.layout{display:grid;grid-template-columns:250px minmax(0,900px);max-width:1210px;margin:auto;gap:36px;padding:32px 24px}.sidebar{position:sticky;top:24px;align-self:start;max-height:calc(100vh - 48px);overflow:auto;padding-right:14px}.brand{font-size:13px;font-weight:700;letter-spacing:.12em;text-transform:uppercase}.sidebar nav{display:grid;gap:3px;margin:20px 0}.sidebar nav a{text-decoration:none;color:var(--muted);font-size:14px;padding:5px 0}.sidebar nav a:hover{color:var(--accent)}.small{font-size:13px;color:var(--muted)}progress{width:100%;accent-color:var(--accent)}main{min-width:0;background:var(--paper);padding:48px 54px;border-radius:12px}.eyebrow{font-size:12px;text-transform:uppercase;letter-spacing:.13em;color:var(--accent);font-weight:700}h1,h2,h3{line-height:1.2}h1{font-family:var(--serif);font-size:clamp(34px,4vw,54px);font-weight:400;margin:20px 0}h2{font-family:var(--serif);font-size:34px;font-weight:400;margin:12px 0 24px}h3{font-size:20px;margin:30px 0 12px}.lead{font-size:21px;line-height:1.6}.intro{color:var(--muted)}.toolbar{display:flex;gap:9px;flex-wrap:wrap;margin:20px 0}section{border-top:1px solid var(--line);padding-top:42px;margin-top:48px;scroll-margin-top:24px}p{margin:0 0 20px}blockquote{font:23px/1.55 var(--serif);border-left:3px solid var(--accent);padding:12px 0 12px 22px;margin:28px 0}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:var(--soft);padding:20px;border-radius:6px;font:14px/1.7 ui-monospace,monospace}table{width:100%;border-collapse:collapse;font-size:14px;line-height:1.55;margin:22px 0;overflow-wrap:anywhere}th,td{text-align:left;vertical-align:top;padding:12px 8px;border-bottom:1px solid var(--line)}th{color:var(--accent)}.source{font-size:12px;color:var(--muted);overflow-wrap:anywhere}.feedback{background:var(--soft);padding:18px;border-radius:6px;margin-top:26px}summary{cursor:pointer;font-weight:600;font-size:14px}label{display:block;font-size:14px;margin-top:14px}textarea{width:100%;margin-top:8px;padding:12px;border:1px solid var(--line);border-radius:5px;background:var(--paper);color:var(--fg);resize:vertical;font-size:16px}.reviewed{display:flex;gap:10px;align-items:center}input[type=checkbox]{width:18px;height:18px;accent-color:var(--accent)}dt{font-weight:650;margin-top:14px}dd{margin:4px 0 16px}li{margin-bottom:12px}.notice{border-left:3px solid var(--accent);padding-left:18px;font-size:14px}.status{font-size:13px;color:var(--muted);min-height:24px}#feedback-output{min-height:220px}footer{margin-top:40px;font-size:13px;color:var(--muted)}@media(prefers-color-scheme:dark){:root{--bg:#142124;--paper:#1b2b2e;--fg:#e8eeeb;--muted:#b5c7c4;--line:#405653;--accent:#8bd3ba;--soft:#263d3d;--button:#b2e5d3;--buttontext:#162c28}}@media(max-width:900px){.layout{display:block;padding:16px}.sidebar{position:static;max-height:none;padding:8px}.sidebar nav{grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.sidebar nav a{font-size:12px}main{padding:30px 25px}.sidebar .small{margin-bottom:12px}}@media(max-width:480px){body{font-size:16px}.layout{padding:8px}main{padding:26px 16px}h2{font-size:29px}.sidebar nav{grid-template-columns:repeat(2,minmax(0,1fr))}th,td{padding:8px 4px;font-size:12px}}@media print{.sidebar,.toolbar,.feedback,#review-panel,.status{display:none!important}.layout{display:block;padding:0}main{padding:0;background:white;color:black}body{background:white;color:black;font-size:11pt}section{break-before:page;border:0;margin:0;padding:0}h2,h3{break-after:avoid}table{font-size:9pt}tr{break-inside:avoid}a{color:inherit}.source{color:#444}pre{background:#eee}footer{display:none}}
</style></head><body><div class="layout"><aside class="sidebar"><div class="brand">Research notebook / 02</div><nav aria-label="Chapters">NAV</nav><label for="reading-progress">Sections reviewed</label><progress id="reading-progress" value="0" max="12"></progress><div id="review-count" class="small">0 of 12 reviewed</div><p class="small">Version 2 · 13 November 2026<br>Reading time: about 30 minutes</p><a href="#review-panel">Collect your feedback ↓</a></aside><main><header><div class="eyebrow">Master’s thesis · Research progress</div><h1>Scheduling AI workloads<br>around energy</h1><p class="lead intro">Testing quantum methods for constrained 24-hour schedules, with classical reference solutions and practical baseline comparisons.</p><p>This document is intended for a technically curious reader who is new to quantum optimization. It follows the research story and separates implemented capabilities, saved observations, and future work.</p><p class="notice"><strong>Revised after your review.</strong> Quantum-method feasibility and scaling are the research focus; the formulation is battery-free, Seren and synthetic stress cases define the workload scope, and FIFO is proposed as a practical baseline. Earlier notes and review markers are retained; please recheck revised chapters.</p><div class="toolbar"><button id="print">Print / save as PDF</button><button id="expand">Open all feedback fields</button></div><p class="notice">Add notes under each chapter. They are saved in this browser when storage is available. To request revisions, use <strong>Collect your feedback</strong> at the end and paste the result into our chat or attach the downloaded feedback file. Notes are not sent automatically.</p><div id="save-status" class="status" role="status" aria-live="polite"></div></header>SECTIONS<section id="review-panel"><div class="eyebrow">Your review</div><h2>Collect your feedback</h2><p>Your comments include stable section identifiers and document version, so revisions can be applied to the right passages. Export before changing browsers or moving the file. A JSON export can also restore your notes here.</p><div class="toolbar"><button class="primary" id="collect">Prepare feedback</button><button id="copy">Copy for chat</button><button id="download">Download feedback JSON</button><button id="import">Import feedback JSON</button><input id="import-file" type="file" accept=".json,application/json" hidden></div><label for="feedback-output">Feedback to paste into the chat</label><textarea id="feedback-output" readonly placeholder="Click Prepare feedback to collect your comments."></textarea><div id="export-status" class="status" role="status" aria-live="polite"></div></section><footer>Prepared from local project source and saved experimental outputs. Numerical experiments were not rerun for this document. The accompanying content.json is the editable narrative source; build.py regenerates this file.</footer></main></div>
<script>
'use strict';
const key='data-center-scheduling-review-v1';
const sections=[...document.querySelectorAll('section[data-title]')];
let state={document:'energy-aware-ai-scheduling',version:2,notes:{},reviewed:{}};
const saveStatus=document.getElementById('save-status');
try{const raw=localStorage.getItem(key);if(raw){const parsed=JSON.parse(raw);if(parsed.document===state.document&&[1,2].includes(parsed.version)&&parsed.notes&&parsed.reviewed)state={...parsed,version:2};}saveStatus.textContent='Browser autosave is available.';}catch(e){saveStatus.textContent='Browser storage is unavailable. Download your feedback to keep it.';}
function updateCount(){const count=sections.filter(s=>state.reviewed[s.id]).length;document.getElementById('reading-progress').value=count;document.getElementById('review-count').textContent=count+' of '+sections.length+' reviewed';}
function restore(){document.querySelectorAll('[data-note]').forEach(el=>{el.value=typeof state.notes[el.dataset.note]==='string'?state.notes[el.dataset.note]:'';});document.querySelectorAll('[data-reviewed]').forEach(el=>el.checked=state.reviewed[el.dataset.reviewed]===true);updateCount();}
function save(){try{localStorage.setItem(key,JSON.stringify(state));saveStatus.textContent='Notes saved in this browser · '+new Date().toLocaleTimeString();}catch(e){saveStatus.textContent='Could not save in this browser. Download your feedback to keep it.';}updateCount();}
restore();
document.querySelectorAll('[data-note]').forEach(el=>el.addEventListener('input',()=>{state.notes[el.dataset.note]=el.value;save();}));
document.querySelectorAll('[data-reviewed]').forEach(el=>el.addEventListener('change',()=>{state.reviewed[el.dataset.reviewed]=el.checked;save();}));
function feedback(){const lines=['Please revise the Energy-aware AI scheduling reading document (version 2) using this feedback.',''];let count=0;for(const s of sections){const note=(state.notes[s.id]||'').trim();if(note){count++;lines.push('## '+s.id+' — '+s.dataset.title,note,'');}}if(!count)lines.push('No comments entered yet.');lines.push('Reviewed sections: '+(sections.filter(s=>state.reviewed[s.id]).map(s=>s.id).join(', ')||'none'));document.getElementById('feedback-output').value=lines.join('\n');return lines.join('\n');}
document.getElementById('collect').onclick=()=>{feedback();document.getElementById('export-status').textContent='Feedback prepared below.';};
document.getElementById('copy').onclick=async()=>{const text=feedback();try{await navigator.clipboard.writeText(text);document.getElementById('export-status').textContent='Copied. Paste into the chat to request revisions.';}catch(e){const box=document.getElementById('feedback-output');box.focus();box.select();document.getElementById('export-status').textContent='Copy is unavailable here. The feedback is selected; press Command+C or Ctrl+C.';}};
document.getElementById('download').onclick=()=>{const payload={...state,exportedAt:new Date().toISOString()};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='scheduling-reading-feedback-v2.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.getElementById('export-status').textContent='Feedback download requested.';};
document.getElementById('import').onclick=()=>document.getElementById('import-file').click();
document.getElementById('import-file').onchange=async(event)=>{const file=event.target.files[0];if(!file)return;try{const obj=JSON.parse(await file.text());if(obj.document!==state.document||![1,2].includes(obj.version)||!obj.notes||!obj.reviewed)throw Error('This is not a compatible version 1 or 2 feedback file.');for(const s of sections){if(typeof obj.notes[s.id]==='string'&&obj.notes[s.id].trim()){state.notes[s.id]=state.notes[s.id]&&state.notes[s.id]!==obj.notes[s.id]?state.notes[s.id]+'\n\n[Imported note]\n'+obj.notes[s.id]:obj.notes[s.id];}if(obj.reviewed[s.id]===true)state.reviewed[s.id]=true;}restore();save();feedback();document.getElementById('export-status').textContent='Feedback imported. Existing comments were preserved.';}catch(e){document.getElementById('export-status').textContent='Import failed: '+e.message;}event.target.value='';};
document.getElementById('print').onclick=()=>window.print();
document.getElementById('expand').onclick=()=>{const open=[...document.querySelectorAll('.feedback')].some(d=>!d.open);document.querySelectorAll('.feedback').forEach(d=>d.open=open);document.getElementById('expand').textContent=open?'Close all feedback fields':'Open all feedback fields';};
</script></body></html>'''
(root/'index.html').write_text(shell.replace('NAV',nav).replace('SECTIONS',sections))
print(root.resolve()/'index.html')
